1	import { useEffect, useRef, useState } from "react";
2	import type { PointerEvent as ReactPointerEvent, ReactNode } from "react";
3	import { flushSync } from "react-dom";
4	import { useMediaQuery } from "@bb/shared-ui/hooks/use-media-query";
5	import { isBlockingOverlayOpen } from "@/lib/swipe-gesture-targets";
6	import type { PaneContent, PaneNode } from "@/lib/split-layout";
7	import { CompactWorkspacePreviewSurface } from "./CompactWorkspacePreviewSurface";
8	import {
9	  abandonsWorkspaceSwipe,
10	  decideWorkspaceSwipe,
11	  describeWorkspacePosition,
12	  hasWorkspaceSwipeIntent,
13	  readWorkspaceSwipeDirection,
14	  resolveWorkspaceSwipePaneId,
15	  resolveWorkspaceSwipeTarget,
16	  shouldIgnoreWorkspaceSwipeTarget,
17	  WORKSPACE_SWIPE_SETTLE_EASING,
18	  WORKSPACE_SWIPE_SETTLE_MS,
19	  type WorkspaceSwipeDirection,
20	} from "./workspaceSwipeGesture";
21	
22	const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";
23	
24	/** The whole standalone surface travels as one layer; both share this box. */
25	const SWIPE_LAYER_CLASS = "flex min-h-0 min-w-0 flex-1 flex-col p-4 md:p-5";
26	
27	type SwipeDestination =
28	  | { kind: "pane"; paneId: string; content: PaneContent }
29	  | { kind: "command-center" }
30	  | { kind: "return"; paneId: string; content: PaneContent | null };
31	
32	interface SwipePreview {
33	  destination: SwipeDestination;
34	  direction: WorkspaceSwipeDirection;
35	}
36	
37	interface SwipeCommit {
38	  announcement: string | null;
39	  run: () => void;
40	}
41	
42	interface SwipeSession {
43	  pointerId: number;
44	  startX: number;
45	  startY: number;
46	  width: number;
47	  deltaX: number;
48	  lastX: number;
49	  lastTimeMs: number;
50	  velocityX: number;
51	  isDragging: boolean;
52	}
53	
54	export interface CompactWorkspaceSwipeHostProps {
55	  /** The complete standalone page surface: header, body, composer, accessories. */
56	  children: ReactNode;
57	  /**
58	   * Identifies what the source layer is showing. Any external change — a
59	   * sidebar pick, a deep link, an agent-driven open — invalidates an in-flight
60	   * gesture, so it cancels rather than committing against stale content.
61	   */
62	  contentKey: string;
63	  /** Gesture-eligible panes in the workspace's persisted reading order. */
64	  panes: readonly PaneNode[];
65	  focusedPaneId: string;
66	  /** Whether a long rightward drag may open the Command Center from here. */
67	  allowsCommandCenter: boolean;
68	  /** Set only while this surface is a Command Center this gesture opened. */
69	  returnPaneId: string | null;
70	  onFocusPane: (paneId: string) => void;
71	  onOpenCommandCenter: () => void;
72	  onReturnFromCommandCenter: () => void;
73	}
74	
75	function findPaneContent(
76	  panes: readonly PaneNode[],
77	  paneId: string,
78	): PaneContent | null {
79	  return panes.find((pane) => pane.paneId === paneId)?.content ?? null;
80	}
81	
82	function isSamePreview(
83	  first: SwipePreview | null,
84	  second: SwipePreview | null,
85	): boolean {
86	  if (first === null || second === null) {
87	    return first === second;
88	  }
89	  if (
90	    first.direction !== second.direction ||
91	    first.destination.kind !== second.destination.kind
92	  ) {
93	    return false;
94	  }
95	  if (first.destination.kind === "pane" && second.destination.kind === "pane") {
96	    return first.destination.paneId === second.destination.paneId;
97	  }
98	  return true;
99	}
100	
101	// Pointer capture is an enhancement: it keeps the gesture attached when the
102	// finger crosses a plugin iframe or the source unmounts. Environments without
103	// it (jsdom, very old WebViews) still get the window-level listeners.
104	function capturePointer(element: HTMLElement, pointerId: number) {
105	  if (typeof element.setPointerCapture === "function") {
106	    element.setPointerCapture(pointerId);
107	  }
108	}
109	
110	function releasePointer(element: HTMLElement, pointerId: number) {
111	  if (
112	    typeof element.releasePointerCapture !== "function" ||
113	    (typeof element.hasPointerCapture === "function" &&
114	      !element.hasPointerCapture(pointerId))
115	  ) {
116	    return;
117	  }
118	  element.releasePointerCapture(pointerId);
119	}
120	
121	function moveLayer(
122	  element: HTMLElement | null,
123	  offsetPx: number,
124	  settling: boolean,
125	) {
126	  if (element === null) {
127	    return;
128	  }
129	  element.style.transform = `translate3d(${offsetPx}px, 0, 0)`;
130	  element.style.transition = settling
131	    ? `transform ${WORKSPACE_SWIPE_SETTLE_MS}ms ${WORKSPACE_SWIPE_SETTLE_EASING}`
132	    : "none";
133	}
134	
135	function clearLayer(element: HTMLElement | null) {
136	  if (element === null) {
137	    return;
138	  }
139	  element.style.transform = "";
140	  element.style.transition = "";
141	  element.style.opacity = "";
142	}
143	
144	/**
145	 * The standalone-compact workspace gesture: a horizontal drag moves the whole
146	 * page surface — header, body, composer, and accessories together — to the
147	 * adjacent pane, or opens the Command Center on a long rightward drag.
148	 *
149	 * Only the source is interactive. The incoming surface is an inert shell drawn
150	 * from pane metadata (see CompactWorkspacePreviewSurface), and the real
151	 * destination mounts only once the route commits, so a drag never starts a
152	 * thread subscription, a plugin runtime, or a composer focus.
153	 */
154	export function CompactWorkspaceSwipeHost({
155	  children,
156	  contentKey,
157	  panes,
158	  focusedPaneId,
159	  allowsCommandCenter,
160	  returnPaneId,
161	  onFocusPane,
162	  onOpenCommandCenter,
163	  onReturnFromCommandCenter,
164	}: CompactWorkspaceSwipeHostProps) {
165	  const prefersReducedMotion = useMediaQuery(REDUCED_MOTION_QUERY);
166	  const hostRef = useRef<HTMLDivElement>(null);
167	  const sourceRef = useRef<HTMLDivElement>(null);
168	  const previewLayerRef = useRef<HTMLDivElement>(null);
169	  const sessionRef = useRef<SwipeSession | null>(null);
170	  const previewRef = useRef<SwipePreview | null>(null);
171	  const teardownRef = useRef<(() => void) | null>(null);
172	  const settleTimerRef = useRef<number | null>(null);
173	  // Stamped with the content it was resolved against, so a surface that changes
174	  // mid-gesture drops the travelling shell on the very same render instead of
175	  // one effect later.
176	  const [previewState, setPreviewState] = useState<{
177	    contentKey: string;
178	    preview: SwipePreview;
179	  } | null>(null);
180	  const preview =
181	    previewState !== null && previewState.contentKey === contentKey
182	      ? previewState.preview
183	      : null;
184	  const [announcement, setAnnouncement] = useState("");
185	  const contentKeyRef = useRef(contentKey);
186	  useEffect(() => {
187	    contentKeyRef.current = contentKey;
188	  });
189	
190	  const abandonGesture = () => {
191	    teardownRef.current?.();
192	    teardownRef.current = null;
193	    sessionRef.current = null;
194	    if (settleTimerRef.current !== null) {
195	      window.clearTimeout(settleTimerRef.current);
196	      settleTimerRef.current = null;
197	    }
198	  };
199	  const abandonGestureRef = useRef(abandonGesture);
200	  useEffect(() => {
201	    abandonGestureRef.current = abandonGesture;
202	  });
203	
204	  useEffect(() => () => abandonGestureRef.current(), []);
205	
206	  // Content changed under the gesture (sidebar pick, deep link, agent open, a
207	  // pruned pane): drop the gesture and put the new surface at rest. What the
208	  // user now sees is committed, so nothing may still travel towards a
209	  // destination chosen for the previous surface.
210	  useEffect(() => {
211	    abandonGestureRef.current();
212	    clearLayer(sourceRef.current);
213	    clearLayer(previewLayerRef.current);
214	    previewRef.current = null;
215	  }, [contentKey]);
216	
217	  const restLayers = () => {
218	    clearLayer(sourceRef.current);
219	    clearLayer(previewLayerRef.current);
220	    previewRef.current = null;
221	    setPreviewState(null);
222	  };
223	
224	  const applyMotion = (deltaX: number, width: number, settling: boolean) => {
225	    if (prefersReducedMotion) {
226	      // Reduced motion keeps the behavior and drops the travelling surface:
227	      // the incoming shell simply states itself, quietly.
228	      const layer = previewLayerRef.current;
229	      if (layer !== null) {
230	        layer.style.opacity = String(Math.min(1, Math.abs(deltaX) / width));
231	      }
232	      return;
233	    }
234	    moveLayer(sourceRef.current, deltaX, settling);
235	    const current = previewRef.current;
236	    if (current !== null) {
237	      const entering = current.direction === "right" ? -width : width;
238	      moveLayer(previewLayerRef.current, deltaX + entering, settling);
239	    }
240	  };
241	
242	  const afterSettle = (run: () => void) => {
243	    if (prefersReducedMotion) {
244	      run();
245	      return;
246	    }
247	    settleTimerRef.current = window.setTimeout(() => {
248	      settleTimerRef.current = null;
249	      run();
250	    }, WORKSPACE_SWIPE_SETTLE_MS);
251	  };
252	
253	  const resolvePreview = (
254	    deltaX: number,
255	    width: number,
256	  ): SwipePreview | null => {
257	    const direction = readWorkspaceSwipeDirection(deltaX);
258	    if (direction === null) {
259	      return null;
260	    }
261	    // A gesture-opened Command Center offers exactly one move: back to the pane
262	    // the gesture started from. Traversal resumes from there.
263	    if (returnPaneId !== null) {
264	      return direction === "left"
265	        ? {
266	            direction,
267	            destination: {
268	              kind: "return",
269	              paneId: returnPaneId,
270	              content: findPaneContent(panes, returnPaneId),
271	            },
272	          }
273	        : null;
274	    }
275	    const target = resolveWorkspaceSwipeTarget({
276	      deltaX,
277	      width,
278	      allowsCommandCenter,
279	    });
280	    if (target === null) {
281	      return null;
282	    }
283	    if (target.kind === "command-center") {
