161	  const workspaceRef = useRef<HTMLDivElement>(null);
162	  const positionsRef = useRef(new Map<HTMLElement, PreservedScrollPosition>());
163	  const previousMaximizedPaneIdRef = useRef(maximizedPaneId);
164	
165	  const captureVisibleScrollPositions = useCallback(() => {
166	    const workspace = workspaceRef.current;
167	    if (workspace === null) {
168	      return;
169	    }
170	    for (const pane of workspace.querySelectorAll<HTMLElement>(
171	      `[${SPLIT_PANE_DATA_ATTR}]:not([aria-hidden="true"])`,
172	    )) {
173	      for (const element of pane.querySelectorAll<HTMLElement>("*")) {
174	        if (element.scrollLeft === 0 && element.scrollTop === 0) {
175	          positionsRef.current.delete(element);
176	          continue;
177	        }
178	        positionsRef.current.set(element, {
179	          left: element.scrollLeft,
180	          top: element.scrollTop,
181	        });
182	      }
183	    }
184	  }, []);
185	
186	  useLayoutEffect(() => {
187	    if (previousMaximizedPaneIdRef.current === maximizedPaneId) {
188	      return;
189	    }
190	    previousMaximizedPaneIdRef.current = maximizedPaneId;
191	
192	    const restore = () => {
193	      const workspace = workspaceRef.current;
194	      for (const [element, position] of positionsRef.current) {
195	        if (workspace === null || !workspace.contains(element)) {
196	          positionsRef.current.delete(element);
197	          continue;
198	        }
199	        element.scrollLeft = position.left;
200	        element.scrollTop = position.top;
201	      }
202	    };
203	
204	    // Restore before paint, then briefly across animation frames so passive
205	    // timeline effects, virtualization, and browser scroll anchoring cannot
206	    // overwrite the saved position while pane visibility settles.
207	    restore();
