1	import { useIsCompactViewport } from "@bb/shared-ui/hooks/use-compact-viewport";
2	import { useMediaQuery } from "@bb/shared-ui/hooks/use-media-query";
3	
4	export const STANDALONE_DISPLAY_MODE_QUERY = "(display-mode: standalone)";
5	
6	/**
7	 * Home-screen iOS web apps predate `(display-mode: standalone)` and report
8	 * their installed state through this non-standard `navigator` flag instead.
9	 * It is a real browser boundary, so read it defensively and narrow to a
10	 * boolean here rather than trusting a typed shape that no lib describes.
11	 */
12	function isLegacyIosStandalone(): boolean {
13	  if (typeof navigator === "undefined" || !("standalone" in navigator)) {
14	    return false;
15	  }
16	  return navigator.standalone === true;
17	}
18	
19	/**
20	 * True only when BB runs as an installed standalone app on a compact viewport —
21	 * the single context whose navigation model replaces browser-tab gestures with
22	 * app-native ones. Safari/Chrome tabs on the same phone, and every desktop
23	 * surface, read false and keep their existing behavior untouched.
24	 *
25	 * Both browser signals are consulted: the standard display-mode query, and the
26	 * legacy iOS flag for home-screen apps that never report a display mode.
27	 */
28	export function useStandaloneCompactPwa(): boolean {
29	  const isCompactViewport = useIsCompactViewport();
30	  const isStandaloneDisplayMode = useMediaQuery(STANDALONE_DISPLAY_MODE_QUERY);
31	  return (
32	    isCompactViewport && (isStandaloneDisplayMode || isLegacyIosStandalone())
33	  );
34	}
